insert into public.boards (id, title, subtitle, framing) values ('hotwash-2026-10-05', 'Hot Wash', '1500 Gateway hot wash · Engagement tools rethink · Oct 5, 2026', 'The commissioner''s question changed. Our tools didn''t. Old tools proved that supporters exist; the live question is whether a yes vote survives an election. Grade every tool on one test: does it give a swing member cover to vote yes.') on conflict (id) do nothing;
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 1, 'Project-level community task force', 'build', 1000, 'County-appointed, published 9 to 11 seat body that turns "no" into "yes if" over a fixed six-week schedule.', 'The one tool that converts "no" into "yes if." Seats: 3 randomly drawn residents from the impact radius with stipend, 2 board appointees from outside the radius, 1 seat offered publicly to the opposition group, 1 school board or principal, 1 fire/EMS or sheriff, 1 co-op or utility (non-voting), 1 county-selected technical reviewer (non-voting). Applicant funds an independent facilitator and the technical reviewer through escrow. RenUSA staffs and keeps minutes, never chairs. Six weeks: charge and by-right alternative; site visit with decibel meter; technical briefing; open public session; drafting; vote and publish. Client publishes a day-one letter stating what it adopts automatically, what is off the table, and that it will accept a no-go finding. Output: a standards document the applicant proffers as conditions, presented by the task force chair, plus two task force seats on the post-approval monitoring committee.', 'Developer-convened reads as captured. Self-selected membership fills with the Facebook group. No day-one letter makes it theater. Open-ended timeline becomes a stall. Client editing the report privately kills it.', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 2, 'Telephone town halls', 'build', 2000, 'Dial the radius onto a live call with the county''s engineer and a task force resident; keypad polls rebuild supporter ID.', 'Closest working replacement for patch-through because it reverses the direction. Client speaks two minutes max. Keypad polls (support with conditions / oppose / undecided) produce hundreds of coded households and phone numbers, which is the supporter ID program that was lost. Commissioner can join and receive results. Monthly through the process. Low five figures per call.', 'Opposition tells people not to pick up. Developer sounds like a developer.', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 3, 'Post-vote defense', 'in', 1000, 'Two-year retainer from vote day that makes the yes vote look good through the next election.', 'Dave: "I like this idea, let''s include it." Quarterly compliance report to the board from the county''s monitor; first-year benefits report with the finance director''s line items before the next budget cycle; named complaint response within a day, logged and reported; weekly construction notices to the radius; developer presence at ribbon cuttings, school board and commissioner town halls. Written into conditions as a monitoring and reporting obligation. Nobody sells it and every commissioner has been burned by its absence.', 'Post-approval spend when the client''s budget line reads "done."', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 4, 'Survivals record', 'in', 2000, 'Track contested data center yes votes 2022 to 2026 to the next election; publish under a university or county association.', 'Dave: "like this one." Universe: contested data center votes in VA, PA, GA, NC, SC, OH, MI, IN, WV, TX (Data Center Watch, Dirt to Data, local news, county minutes). Record roll call and attached conditions per member; follow each to the next election (ran, won, margin change, opponent campaigned on it, recall); no-voters as control; code what survivors had in common. Private one-pager per commissioner. One researcher plus AI-assisted scraping, four to six weeks for three states, updated each December. First cut after November 2026. Page-one caveats: incumbents usually win, small samples, pattern study not proof. Must include the Prince William board chair losing her 2023 primary after Digital Gateway as the obvious counterexample (UNVERIFIED in the source thread; confirm before use).', 'Small samples and incumbency advantage make it easy to dismiss. Needs an owner and funding decision.', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 5, 'Governor standard as floor, county conditions as ceiling', 'in', 3000, 'Cite "the state benchmark," never the governor by name; the county holds enforcement.', 'Dave agreed the floor/ceiling framing. County holds the enforcement: noise monitor, water cap, cancellation trigger. Hyperscaler Ratepayer Protection Pledge is a footnote showing the tenant is already bound nationally. For non-hyperscaler clients, pledge terms must bind any operator via lease requirement plus condition. Product idea: state-by-state matrix of governor standards, pledge signatories and PUC large-load tariffs, kept current.', 'County boards resent state capitals and some governors are politically toxic in some counties. Most RenUSA clients are developers, not pledge signatories.', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 6, 'Polling, reframed', 'in', 4000, 'Named local pollster, public methodology, district crosstabs. Measure salience and conditional support, never the raw question.', 'Dave: "great but limited," "not a silver bullet." Measure salience vs taxes/roads/schools, conditional support given specific conditions, the by-right alternative comparison, and whether respondents attended or posted (to size the loud room against the district). Deliberative variant: poll, balanced briefing, re-poll. Let the county pick or co-fund the pollster. Never ask "do you support a data center," which loses everywhere.', 'Applicant-paid polling reads as advocacy unless the county picks or co-funds the pollster.', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 7, 'Institutions that ask, not support', 'in', 5000, 'Superintendent and sheriff at the podium with a number and a cut list from their own budget documents.', 'Backed by a signed benefit agreement with escrowed line items. RenUSA already works hand in hand with economic development and school superintendents and boards, but they only "support," they don''t "ask." Economic development is a weak validator because supporting projects is their job.', 'Endorsing on a projection that comes in at half makes the school board the next opponent. Some boards fear looking bought.', 'cover', 'Schools and education outreach', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 8, 'Peer-to-peer texting', 'debate', 1000, 'Texts from local numbers with a named staffer who answers; supporter ID built in.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 9, 'Paid canvass, including deep canvass', 'debate', 2000, 'Door-to-door in the impact radius, with a deep canvass variant for longer conversations.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 10, 'Geofenced digital to an ID landing page', 'debate', 3000, 'Geofenced digital driving residents to a supporter ID landing page. Identification, not persuasion.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 11, 'Mail, repurposed', 'debate', 4000, 'Hand-addressed invitation from the project lead with a personal cell number, meeting date, and a task force application replacing the BRM card.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 12, 'Small-format events', 'debate', 5000, 'Kitchen tables, office hours, church and civic circuits.', '', '', 'community', 'Public events', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 13, 'Local radio and the paper', 'debate', 6000, 'Hand the one remaining reporter the documents early.', '', '', 'community', 'Earned media, local', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 14, 'Short video answers to the viral claim', 'debate', 7000, 'Answer the viral claim of the week from a named person, with the document attached.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 15, 'Opposition mapping', 'debate', 8000, 'Local vs imported opposition, and who is running for office.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 16, 'Commissioner interview series and whip count', 'debate', 9000, 'Early interviews (what would let you vote yes) and a whip count with no rounding.', '', '', 'cover', 'Council member engagement', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 17, 'Public running FAQ with receipts', 'debate', 10000, 'A living FAQ with source documents and visible corrections.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 18, 'Seat for the opposition leader', 'debate', 11000, 'Offer the opposition leader a seat at the conditions table.', '', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 19, 'By-right alternative rendering', 'care', 1000, 'To-scale rendering of what the ordinance already allows, same vantage as the project rendering, with truck counts and revenue.', 'Dave: "we have certainly used this. Sometimes it gets the politicians really mad." Fix: county planning staff produces it in their own report; task force sees it in week one; landowner speaks to it; never say "we will," say "the ordinance allows." A week-one tool for staff and task force, never a hearing-night tool from the developer.', 'Only works where the by-right use is real. From the developer on hearing night it reads as a threat.', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 20, 'Yard signs', 'care', 2000, 'A visible signal of support.', 'Only where the middle is already proven.', 'Counted as money and vandalized.', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 21, 'Persuasion mail and BRM cards', 'out', 1000, 'Volume mail and business reply cards to prove supporters exist.', 'Out. Cause of the problem: applicant-side volume now reads as manufactured and gets screenshotted as outside money.', '', 'community', 'Direct mail and newspaper ads', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 22, 'Patch-through and vendor supporter ID calls', 'out', 2000, 'Phone ID and patch-through calls to commissioners.', 'Out. Phone ID is mechanically dead (cell-only households, spam labeling) and patch-through volume is discounted.', '', 'community', 'Patch-through calls', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 23, 'Relational organizing apps', 'out', 3000, 'Reach, Impactive and similar supporter-to-network apps.', 'Dave: "really unrealistic." Nobody texts their cousin about a data center, and the social cost in a small county is real. Direct-stake people (trades, landowner family, EMS chief) already talk to their networks without an app.', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 24, 'Precinct-level electoral math per commissioner', 'out', 4000, 'Model each commissioner''s re-election math at the precinct level.', 'Dave: "seems hard." Buildable as a desk product, but delivery is presumptuous and needs a trusted local intermediary.', '', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 25, 'Property value guarantees', 'out', 5000, 'Guarantee neighbors against lost property value.', 'Dave: "realistic, but not as effective as you''d think. They all think it''s developer bullshit." Bonded, county-held version is "unlikely to happen." Cash-now neighbor payment and buyout option discussed but not adopted.', '', 'community', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 26, 'Property value studies', 'out', 6000, 'Commissioned studies showing no property value impact.', 'Out. Paper nobody believes.', '', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 27, 'Staff report as a product', 'out', 7000, 'Packaging the county staff report as a RenUSA product.', 'Dave: "most places I''ve seen could care less about the staff if politically they don''t love it." Keep as a hygiene checklist item, no product.', '', 'cover', null, null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 28, 'Digital persuasion ads and astroturf', 'out', 8000, 'Pre-vote persuasion ads, hearing-timed sponsorships, any undisclosed voice.', 'Out. Applicant-side persuasion volume is discounted or counterproductive; undisclosed voice is a reputational risk.', '', 'community', 'Paid digital ads', null);
insert into public.cards (board_id, n, title, col, ord, description, verdict, breaks, track, survey_tactic, created_by) values ('hotwash-2026-10-05', 29, 'Labor and PLA', 'parking', 1000, 'Union allies and project labor agreements. Top-scoring tactic on 1500 Gateway; not yet placed on the board.', 'Added from the 1500 Gateway team survey: highest on both execution (4.8) and impact (4.4). Named twice as the thing to replicate: turnout at multiple phases, plus follow-up utility (LTEs, written comments, media quotes). Place it during the session.', '', 'cover', 'Labor and PLA', null);
insert into public.surveys (id, board_id, title, respondents, note, tactics, responses, takeaways) values ('gateway1500', 'hotwash-2026-10-05', '1500 Gateway team survey', 5, 'Staff self-assessment, 5 responses, 1 to 5 scale', '[{"tactic":"Council member engagement","exec_avg":3.2,"exec_hi":4,"exec_lo":2,"exec_n":5,"impact_avg":2.4,"impact_hi":4,"impact_lo":1,"impact_n":5},{"tactic":"Coalition building","exec_avg":3.4,"exec_hi":4,"exec_lo":2,"exec_n":5,"impact_avg":3.6,"impact_hi":5,"impact_lo":2,"impact_n":5},{"tactic":"Labor and PLA","exec_avg":4.8,"exec_hi":5,"exec_lo":4,"exec_n":5,"impact_avg":4.4,"impact_hi":5,"impact_lo":3,"impact_n":5},{"tactic":"Earned media, local","exec_avg":4.2,"exec_hi":5,"exec_lo":3,"exec_n":5,"impact_avg":3.4,"impact_hi":4,"impact_lo":2,"impact_n":5},{"tactic":"Earned media, national and trade","exec_avg":3.8,"exec_hi":5,"exec_lo":3,"exec_n":5,"impact_avg":2,"impact_hi":4,"impact_lo":1,"impact_n":5},{"tactic":"Paid digital ads","exec_avg":3.2,"exec_hi":5,"exec_lo":1,"exec_n":5,"impact_avg":2,"impact_hi":3,"impact_lo":1,"impact_n":5},{"tactic":"Patch-through calls","exec_avg":1.8,"exec_hi":3,"exec_lo":1,"exec_n":5,"impact_avg":1.4,"impact_hi":3,"impact_lo":1,"impact_n":5},{"tactic":"Direct mail and newspaper ads","exec_avg":3.4,"exec_hi":4,"exec_lo":3,"exec_n":5,"impact_avg":1.8,"impact_hi":3,"impact_lo":1,"impact_n":5},{"tactic":"Digital advocacy","exec_avg":3,"exec_hi":4,"exec_lo":2,"exec_n":4,"impact_avg":2,"impact_hi":3,"impact_lo":1,"impact_n":4},{"tactic":"Public events","exec_avg":3.4,"exec_hi":5,"exec_lo":2,"exec_n":5,"impact_avg":3.6,"impact_hi":4,"impact_lo":3,"impact_n":5},{"tactic":"Hearing night","exec_avg":4.4,"exec_hi":5,"exec_lo":3,"exec_n":5,"impact_avg":3.6,"impact_hi":5,"impact_lo":3,"impact_n":5},{"tactic":"Schools and education outreach","exec_avg":2.8,"exec_hi":5,"exec_lo":1,"exec_n":5,"impact_avg":2.6,"impact_hi":4,"impact_lo":1,"impact_n":5},{"tactic":"Opposition research and rapid response","exec_avg":4,"exec_hi":5,"exec_lo":3,"exec_n":5,"impact_avg":3.6,"impact_hi":5,"impact_lo":3,"impact_n":5},{"tactic":"Messaging and materials","exec_avg":4.6,"exec_hi":5,"exec_lo":4,"exec_n":5,"impact_avg":3.8,"impact_hi":5,"impact_lo":2,"impact_n":5},{"tactic":"Client counsel","exec_avg":4.2,"exec_hi":5,"exec_lo":4,"exec_n":5,"impact_avg":4.2,"impact_hi":5,"impact_lo":3,"impact_n":5}]'::jsonb, '[{"replicate":"The coalition we built and supported.","never":"Patch through calls.","decision":"Meeting with the City Council directly."},{"replicate":"The build your own personalized letter/comment prior to the hearing and the flodesk emails as community and stakeholder outreach. I think the letter/comment builder should be used at every landowners dinner and pre hearing event","never":null,"decision":"Sending mailers that allowed responses and not doing the patch-thru phone calls would have made the biggest differences here. Not because the tactics are bad but I don''t think that we anticipated the hostility both of those actions would receive. Having the councilwoman post her negative comments to our postcard and post them online along with her and others saying that the calls were robotic-calls added addition fire to the flame/talking points for opposition."},{"replicate":"From what I saw, the Labor engagement in general. I know this is already a strong point we utilize in nearly every project, but at multiple phases, I was wowed by the turnout and engagement from our union allies. Even in a losing battle, the impact was intense and the follow-up utility (the LTE''s, written comments, media quotes) were fantastic.","never":"I''m hesitant to say this, but I''m not sure in a similar case to this, the reply mail. I don''t remember if anything got mailed in at all. Different cases and factors, mail away. But I''m just not sure about it in similar situations.","decision":"Hindsight is 20/20, but I firmly believe more aggressive engagement at an earlier juncture in the project would have tipped the scales at least in our favor. Jumping in to the project as late as I did and still seeing others (outside of the RenUSA team) standing behind a slow pace, not really wanting to ruffle too many feathers was a bit shocking. I understand that there were other factors like local advocates not wanting to damage their reps, but that''s the point of what we''re working together for, to see results."},{"replicate":"Constant campaign comms, frequent client engagement, working through conflict with the client, speed of approvals, being advisors v. order takers","never":"Skip the real community engagement phase (client dependent), not do community meetings","decision":"A harder political campaign run at the TOD and earlier, poured into all communications components of the campaign - lobbying, community engagement, messaging, etc."},{"replicate":"Union outreach","never":"Patch calls. Having difficulty with this one.","decision":"Public information session; door-to-door outreach."}]'::jsonb, '["Labor and PLA scored highest on both execution (4.8) and impact (4.4).","Client counsel was the only other tactic at 4 or above on both.","Patch-through calls scored lowest on both (1.8 execution, 1.4 impact). Three of the four \"never do again\" answers named patch calls or reply mail; one respondent left it blank.","The biggest gaps between execution and impact were national and trade earned media (-1.8), direct mail and newspaper ads (-1.6) and paid digital (-1.2). The team rated these as well run but thought they did little for the outcome.","Council member engagement had an impact average of 2.4, and several respondents said earlier or more direct council engagement was the decision most likely to change the outcome.","Paid digital ads and schools outreach had the widest spread on execution (5 to 1), so the team disagrees on how well those went."]'::jsonb) on conflict (id) do nothing;
